const seen = new Set();
const output = [];

for (const item of $input.all()) {
  if (!item || !item.json) continue;

  const json = item.json;

  const key =
    json.link ||
    json.url ||
    json.guid ||
    json.id ||
    json.title;

  if (!key) continue;

  const safeKey = String(key);

  if (seen.has(safeKey)) continue;

  seen.add(safeKey);

  output.push({ json });
}

return output;

const seen = new Set();
const output = [];

for (const item of $input.all()) {
  if (!item || !item.json) continue;

  const json = item.json;

  const key =
    json.link ||
    json.url ||
    json.guid ||
    json.id ||
    json.title;

  if (!key) continue;

  const safeKey = String(key);

  if (seen.has(safeKey)) continue;

  seen.add(safeKey);

  output.push({ json });
}

return output;

const items = $input.all() || [];

const articles = [];
let count = 0;

for (const item of items) {

  if (!item || !item.json) continue;

  const j = item.json;

  const title = (j.title || 'Sem título').toString();
  const link = (j.link || j.url || '').toString();

  articles.push({
    title,
    link
  });

  count++;
}

if (articles.length === 0) {
  articles.push({
    title: 'Nenhuma notícia encontrada',
    link: ''
  });
}

const prompt =
`Você é um analista de IA.

Analise as seguintes notícias da semana:

${articles.map((a, i) => `${i + 1}. ${a.title}`).join('\n')}

Gere um relatório com:
- Destaques
- Tendências
- Oportunidades
- Resumo executivo

Seja direto e profissional.`;

return [
  {
    json: {
      total: count,
      articles,
      prompt
    }
  }
];

let aggData = {};
let gptText = 'Relatório não gerado.';

// 🔒 PEGAR DADOS DO AGGREGATE COM SEGURANÇA
try {
  const node = $('Aggregate').first();
  if (node && node.json) {
    aggData = node.json;
  }
} catch (e) {
  aggData = {};
}


const gpt = $input.first()?.json || {};

if (gpt?.choices?.[0]?.message?.content) {
  gptText = gpt.choices[0].message.content;
}
// fallback (às vezes vem assim)
else if (gpt?.message?.content) {
  gptText = gpt.message.content;
}
// fallback bruto
else if (gpt?.text) {
  gptText = gpt.text;
}
// fallback final
else {
  gptText = JSON.stringify(gpt).slice(0, 500);
}

return [
  {
    json: {
      total: aggData.total || 0,
      articles: aggData.articles || [],
      gptReport: gptText
    }
  }
];

const httpResponse = $input.first()?.json || {};
const gptReport = httpResponse?.choices?.[0]?.message?.content || 'Relatorio nao gerado.';

// SAFE GET do node anterior
const aggregatedNode = $('Build GPT Prompt').first();
const aggregated = aggregatedNode ? aggregatedNode.json : {};

const stats = aggregated?.stats || [];
const total = aggregated?.total || 0;
const articles = aggregated?.articles || [];

// TOP STAT SAFE
const topStat = (stats && stats.length > 0) ? stats[0] : null;

// TABLE
const statsRows = stats.map(s =>
  '<tr><td>' + (s.category || '-') + '</td><td>' + (s.count || 0) + '</td><td>' + (s.percentage || 0) + '%</td></tr>'
).join('');

// GROUP BY CATEGORY
const byCategory = {};
articles.forEach(a => {
  const cat = a.category || 'General AI';
  if (!byCategory[cat]) byCategory[cat] = [];
  byCategory[cat].push(a);
});

// ARTICLES HTML
const articleSections = Object.entries(byCategory).map(([cat, arts]) => {
  const artList = arts.map(a =>
    '<li><a href="' + (a.link || '#') + '" target="_blank">' + (a.title || 'Sem titulo') + '</a><br><small>' + (a.summary || '') + '</small></li>'
  ).join('');
  return '<h3>' + cat + '</h3><ul>' + artList + '</ul>';
}).join('');

// REPORT FORMAT
const reportHtml = (gptReport || '')
  .replace(/## (.+)/g, '<h2>$1</h2>')
  .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
  .replace(/\n\n/g, '</p><p>')
  .replace(/\n/g, '<br>');

// DATE
const weekDate = new Date().toLocaleDateString('pt-BR', {
  day: '2-digit',
  month: 'long',
  year: 'numeric'
});

// HTML (APENAS CSS ALTERADO)
const html = '<!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8"><title>Inteli Academy - AI News | ' + weekDate + '</title><style>body{font-family:Arial,sans-serif;max-width:680px;margin:0 auto;padding:20px;color:#1a1a1a;background:#ffffff}header{border-bottom:2px solid #000;padding-bottom:10px;margin-bottom:20px}h1{font-size:24px;margin:0}.subtitle{color:#555;font-size:14px}.summary-box{background:#000;color:#fff;padding:16px;margin-bottom:24px}.summary-box h2{margin:0 0 10px 0;font-size:12px;text-transform:uppercase}.stat{margin-bottom:8px}.stat-number{font-size:20px;font-weight:bold}.stat-label{font-size:12px}table{width:100%;border-collapse:collapse;margin-bottom:24px}th{text-align:left;border-bottom:2px solid #000;padding:8px 0;font-size:12px}td{padding:8px 0;border-bottom:1px solid #ddd}h2{font-size:18px;margin:24px 0 10px 0}h3{font-size:14px;margin:16px 0 6px 0}p{line-height:1.6}ul{padding-left:18px}li{margin-bottom:10px}a{color:#000;text-decoration:underline}small{color:#777;font-size:12px}footer{border-top:1px solid #ddd;margin-top:30px;padding-top:10px;font-size:12px;color:#777}</style></head><body>'
  + '<header><h1>Inteli Academy - AI News</h1><p class="subtitle">Relatorio semanal de Inteligencia Artificial | ' + weekDate + '</p></header>'
  + '<div class="summary-box"><h2>Resumo da Semana</h2><div class="stats-grid">'
  + '<div class="stat"><span class="stat-number">' + total + '</span><span class="stat-label">Noticias</span></div>'
  + '<div class="stat"><span class="stat-number">' + stats.length + '</span><span class="stat-label">Categorias</span></div>'
  + '<div class="stat"><span class="stat-number">' + (topStat ? topStat.percentage + '%' : '0%') + '</span><span class="stat-label">' + (topStat ? topStat.category : '-') + '</span></div>'
  + '</div></div>'
  + '<h2>Distribuicao por Categoria</h2><table><thead><tr><th>Categoria</th><th>Noticias</th><th>Percentual</th></tr></thead><tbody>' + statsRows + '</tbody></table>'
  + '<p>' + reportHtml + '</p>'
  + '<h2>Todas as Noticias da Semana</h2>' + (articleSections || '<p>Nenhuma noticia encontrada</p>')
  + '<footer><p>Inteli Academy - Clube de IA do Inteli | Gerado automaticamente via n8n + GPT-4o | ' + weekDate + '</p></footer>'
  + '</body></html>';

return [{
  json: {
    html,
    subject: 'Inteli Academy - AI News | ' + weekDate + ' | ' + total + ' noticias',
    report: gptReport,
    total,
    stats
  }
}];
